export const events = {
	appearanceCorners: (callback: (payload: Corners) => void) => listen<Corners>("appearance.corners", callback),
	appearanceKeyboard: (callback: (payload: boolean) => void) => listen<boolean>("appearance.keyboard", callback),
	appearanceLines: (callback: (payload: Lines) => void) => listen<Lines>("appearance.lines", callback),
	appearanceMotion: (callback: (payload: Motion) => void) => listen<Motion>("appearance.motion", callback),
	appearancePosture: (callback: (payload: Posture) => void) => listen<Posture>("appearance.posture", callback),
	appearanceTypography: (callback: (payload: Typography) => void) => listen<Typography>("appearance.typography", callback),
	documentChanged: (callback: (payload: DocumentView) => void) => listen<DocumentView>("document.changed", callback),
	kestrelPalette: (callback: (payload: Palette) => void) => listen<Palette>("kestrel.palette", callback),
	saveProgress: (callback: (payload: number) => void) => listen<number>("save.progress", callback),
	scanFinished: (callback: (payload: ScanError | null) => void) => listen<ScanError | null>("scan.finished", callback),
	scanPreview: (callback: (payload: Uint8Array) => void) => listen<Uint8Array>("scan.preview", callback),
	scannersChanged: (callback: (payload: Scanner[]) => void) => listen<Scanner[]>("scanners.changed", callback),
};

export type AppIconStyle = "default" | "tinted" | "clear";

export type AppIcons = {
	style: AppIconStyle,
	glyphs: string,
	tinted: IconPaint,
	clear: IconPaint,
};

export type AppState = {
	document: DocumentView,
	scanners: Scanner[],
	settings: Settings,
	readingLanguages: string[] | null,
} & Appearance;

export type Appearance = {
	palette: Palette | null,
	typography: Typography,
	motion: Motion,
	corners: Corners,
	lines: Lines,
	posture: Posture,
	keyboard: boolean,
	locale: Locale,
};

export type Connection = "network" | "usb";

export type Corners = "rounded" | "square";

export type DocumentView = {
	mode: Mode,
	pages: PageView[],
};

export type Feed = "glass" | "feeder" | "bothSides";

export type Format = "pdf" | "jpeg" | "png";

export type IconPaint = {
	plate: string,
	ink: string,
	shade: string,
	rim: number,
};

export type Lines = "none" | "lines" | "scanlines";

export type Locale = {
	languages: string[],
	formats: string,
	fixed: boolean,
};

export type Mode = "colour" | "grey" | "blackAndWhite";

export type Motion = "full" | "reduced" | "off";

export type PageView = {
	id: string,
	image: string | null,
	thumbnail: string | null,
	source: string,
	version: number,
	width: number,
	height: number,
	quad: Quad,
	turns: number,
};

export type Palette = {
	accent: string,
	wallpaperAccent: string,
	pureBlack: boolean,
	colors: SchemeColors,
	terminal: SchemeColors,
	appIcons: AppIcons,
	taskbar: import("@luft/ui").TaskbarLooks,
};

export type PaperSize = "automatic" | "a4" | "letter";

/**  Whether the computer is used as a laptop or folded into a tablet. */
export type Posture = "laptop" | "tablet";

export type Quad = [([number, number]), ([number, number]), ([number, number]), ([number, number])];

export type Saved = {
	path: string,
	files: string[],
};

export type ScanError = { kind: "cancelled" } | { kind: "busy" } | { kind: "feederEmpty" } | { kind: "gone" } | { kind: "identityChanged" } | { kind: "failed"; message: string };

export type Scanner = {
	id: string,
	name: string,
	connection: Connection,
	feeds: Feed[],
	identityChanged: boolean,
};

export type SchemeColors = {
	light: { [key in string]: string },
	dark: { [key in string]: string },
};

export type Settings = {
	languages: string[],
	paper: PaperSize,
	fine: boolean,
	addresses: string[],
	scanner: string | null,
};

export type Typography = {
	interface: string | null,
	monospace: string | null,
	textScale: number,
};
